#!/usr/bin/python3

"""
    External services module private methods.
"""

__author__ = "Velocity Support"
__email__ = "velocity.support@nokia.com"

import base64
from velocity_communicator.log.log import Log


class ExternalPrivates(object):
    """
        Class with definicion of private methods related to
        external services module.
    """

    logger = Log.get_logger("velocityclient")

    def _get_base64_auth(self, username, password):
        user = username.encode('utf-8')
        passwrd = password.encode('utf-8')
        return base64.b64encode(user + b':' + passwrd).decode('utf-8')
